changeSet.sql:
CREATE TABLE domaine ( id_domaine SERIAL, domaine VARCHAR(50) NOT NULL, PRIMARY KEY (id_domaine), UNIQUE (domaine) );
CREATE TABLE question ( id_question SERIAL, question TEXT NOT NULL, id_domaine INTEGER NOT NULL, PRIMARY KEY (id_question), UNIQUE (question), FOREIGN KEY (id_domaine) REFERENCES domaine (id_domaine) );
CREATE TABLE reponse ( id_reponse SERIAL, reponse TEXT NOT NULL, note NUMERIC(15, 2) NOT NULL, id_question INTEGER NOT NULL, PRIMARY KEY (id_reponse), FOREIGN KEY (id_question) REFERENCES question (id_question) );
CREATE TABLE resultat ( id_resultat SERIAL, note NUMERIC(15, 2), date_resultat TIMESTAMP, id_domaine INTEGER NOT NULL, id_talent INTEGER NOT NULL, PRIMARY KEY (id_resultat), FOREIGN KEY (id_domaine) REFERENCES domaine (id_domaine), FOREIGN KEY (id_talent) REFERENCES talent (id_talent) );
